import math

def count_divisors(n):
    """Calculates tau(n), the number of positive divisors of n."""
    if n <= 0:
        return 0
    if n == 1:
        return 1

    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            # i is a divisor
            count += 1
            # n/i is also a divisor, unless i*i = n
            if i * i != n:
                count += 1
    return count

def d(n):
    """Calculates d(n) = tau(n) - 2."""
    tau_n = count_divisors(n)
    return tau_n - 2

def search_a2(limit):
    """Searches for n <= limit such that d(n) = d(n+735) = 2."""
    solutions = []
    for n in range(1, limit + 1):
        d_n = d(n)
        d_n_plus_735 = d(n + 735)

        if d_n == 2 and d_n_plus_735 == 2:
            solutions.append((n, d_n, d_n_plus_735))

    return solutions

# Search up to n=2000
solutions = search_a2(2000)

print("--- Search Results for a=2 (n <= 2000) ---")
if solutions:
    print(f"Found {len(solutions)} solutions.")
    for n, d_n, d_n_plus_735 in solutions:
        print(f"n = {n}: d({n}) = {d_n}, d({n+735}) = {d_n_plus_735}")
else:
    print("No solutions found in the range n <= 2000.")
